package com.acme.warehouse.stock;

/**
 * Guards a stock movement against driving a bin's quantity negative.
 */
public class NonNegativeStockGuard {

    private final StockRepository stock;

    public NonNegativeStockGuard(StockRepository stock) {
        this.stock = stock;
    }

    public void assertAvailable(String binId, int requestedDelta) {
        int current = stock.onHand(binId);
        if (current + requestedDelta < 0) {
            throw new NegativeStockException(binId, current, requestedDelta);
        }
    }
}

class NegativeStockException extends RuntimeException {
    public NegativeStockException(String bin, int current, int delta) {
        super("Bin " + bin + " has " + current + " on hand; requested change " + delta);
    }
}

