package com.acme.warehouse.valuation;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/**
 * Rolls up stock value per SKU using on-hand quantity and standard cost.
 */
public class InventoryValuationService {

    private final StockRepository stock;
    private final CostRepository costs;

    public InventoryValuationService(StockRepository stock, CostRepository costs) {
        this.stock = stock;
        this.costs = costs;
    }

    public ValuationReport valueAll() {
        List<String> skus = stock.distinctSkus();
        BigDecimal grandTotal = BigDecimal.ZERO;
        ValuationReport report = new ValuationReport();
        for (String sku : skus) {
            int qty = stock.totalOnHand(sku);
            BigDecimal cost = costs.standardCostFor(sku);
            BigDecimal value = cost.multiply(BigDecimal.valueOf(qty)).setScale(2, RoundingMode.HALF_UP);
            report.add(new SkuValuation(sku, qty, cost, value));
            grandTotal = grandTotal.add(value);
        }
        report.setTotal(grandTotal);
        return report;
    }
}

