import java.math.BigDecimal;

/** Computes shrinkage value: difference between recorded stock and physical count. */
public class ShrinkageValueCalculator {
    private final StockRepository stock;
    private final CostRepository costs;

    public ShrinkageValueCalculator(StockRepository stock, CostRepository costs) {
        this.stock = stock;
        this.costs = costs;
    }

    public BigDecimal shrinkageValue(String sku, int physicalCount) {
        int recorded = stock.totalOnHand(sku);
        int diff = recorded - physicalCount;
        return costs.standardCostFor(sku).multiply(BigDecimal.valueOf(Math.abs(diff)));
    }
