package com.acme.warehouse.rules;

import java.util.List;

/**
 * Prevents the same SKU existing in two temperature zones in the same warehouse.
 */
public class SingleZonePerSkuRule {

    private final StockRepository stock;
    private final BinRepository bins;

    public SingleZonePerSkuRule(StockRepository stock, BinRepository bins) {
        this.stock = stock;
        this.bins = bins;
    }

    public void assertSingleZone(String warehouseId, String sku, String targetBinId) {
        String targetZone = bins.require(targetBinId).getZone();
        List<String> binsHolding = stock.binsWithStock(warehouseId, sku);
        for (String b : binsHolding) {
            if (!bins.require(b).getZone().equals(targetZone)) {
                throw new ZoneConflictException(sku, targetZone, bins.require(b).getZone());
            }
        }
    }
}

