package com.acme.warehouse.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Writes a stock movement ledger entry for every stock-affecting event.
 */
public class StockMovementLedger {

    private final EntityManager em;

    public StockMovementLedger(EntityManager em) {
        this.em = em;
    }

    public void record(String binId, String sku, int signedDelta, String reason, String userId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            StockMovement mv = new StockMovement();
            mv.setBinId(binId);
            mv.setSku(sku);
            mv.setSignedDelta(signedDelta);
            mv.setReason(reason);
            mv.setUserId(userId);
            mv.setOccurredAt(Instant.now());
            em.persist(mv);
            tx.commit();
        } catch (RuntimeException e) {
            tx.rollback();
            throw e;
        }
    }
}

