/* replenishment_job.c - create purchase suggestions for SKUs below reorder point */
#include <stdio.h>
#include "warehouse_db.h"

int run_replenishment(const char *warehouse_id) {
    db_cursor_t *cur = NULL;
    if (db_open_low_stock_cursor(&cur, warehouse_id) != DB_OK) return -1;

    int suggestions = 0;
    stock_row_t row;
    while (db_stock_cursor_next(cur, &row) == DB_OK) {
        if (row.on_hand >= row.reorder_point) continue;
        int qty = row.target_level - row.on_hand;
        if (qty <= 0) continue;
        if (db_insert_purchase_suggestion(warehouse_id, row.sku, qty) != DB_OK) {
            db_close_cursor(cur);
            return -2;
        }
        suggestions++;
    }
    db_close_cursor(cur);
    return suggestions;
}

